-- Migration: Tạo bảng danh mục Đơn vị vận hành & Khai thác (operating_organizations) gọn nhẹ và seed 526 bản ghi từ hệ thống cũ
CREATE TABLE IF NOT EXISTS public.operating_organizations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code VARCHAR(50) NOT NULL UNIQUE,
    parent_code VARCHAR(50),
    name VARCHAR(255) NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_operating_organizations_code ON public.operating_organizations (code);

